import{_ as a,o as t,c as n,a5 as s}from"./chunks/framework.pJebtgMf.js";const m=JSON.parse('{"title":"AI 动态 · 2026-09-04","description":"","frontmatter":{"title":"AI 动态 · 2026-09-04","date":"2026-09-04T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-09/ai-news-2026-09-04.md","filePath":"news/2026-09/ai-news-2026-09-04.md","lastUpdated":null}'),r={name:"news/2026-09/ai-news-2026-09-04.md"};function o(i,e,l,p,c,d){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="ai-动态-·-2026-09-04" tabindex="-1">AI 动态 · 2026-09-04 <a class="header-anchor" href="#ai-动态-·-2026-09-04" aria-label="Permalink to &quot;AI 动态 · 2026-09-04&quot;">​</a></h1><blockquote><p>截至 2026-09-04。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="数据中心开发商-crusoe-据报以-300-亿美元估值融资-30-亿美元" tabindex="-1">数据中心开发商 Crusoe 据报以 300 亿美元估值融资 30 亿美元 <a class="header-anchor" href="#数据中心开发商-crusoe-据报以-300-亿美元估值融资-30-亿美元" aria-label="Permalink to &quot;数据中心开发商 Crusoe 据报以 300 亿美元估值融资 30 亿美元&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-09-04">2026-09-04</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/46dc98ab369c.jpg" alt="配图"></p><p>数据中心开发商 Crusoe 据报完成新一轮 30 亿美元融资，估值达 300 亿美元。该轮融资落地前，Crusoe 刚与 Jane Street 签下 130 亿美元合同，显著推高了市场对其算力基础设施前景的预期。对读者：关注 AI 算力基础设施赛道的资本热度与头部客户绑定逻辑。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/09/03/crusoe-reportedly-raises-3b-at-a-30b-valuation/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="accel-据报洽谈领投-thinking-machines-10-亿美元融资-估值-400-亿美元" tabindex="-1">Accel 据报洽谈领投 Thinking Machines 10 亿美元融资，估值 400 亿美元 <a class="header-anchor" href="#accel-据报洽谈领投-thinking-machines-10-亿美元融资-估值-400-亿美元" aria-label="Permalink to &quot;Accel 据报洽谈领投 Thinking Machines 10 亿美元融资，估值 400 亿美元&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-09-04">2026-09-04</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/3ebda6a72dec.jpg" alt="配图"></p><p>据多家媒体报道，Accel 正洽谈领投 Thinking Machines 新一轮 10 亿美元融资，估值高达 400 亿美元。该初创公司年度经常性收入已超过 1 亿美元，高增长与高估值并存。对读者：关注前沿 AI 实验室的估值泡沫风险与商业化验证进度。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/09/03/accel-reportedly-in-talks-to-lead-1b-round-for-thinking-machines-at-40b-valuation/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="openai-为避开-elon-musk-放弃年收入超-10-亿美元的-cursor-合作" tabindex="-1">OpenAI 为避开 Elon Musk 放弃年收入超 10 亿美元的 Cursor 合作 <a class="header-anchor" href="#openai-为避开-elon-musk-放弃年收入超-10-亿美元的-cursor-合作" aria-label="Permalink to &quot;OpenAI 为避开 Elon Musk 放弃年收入超 10 亿美元的 Cursor 合作&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Wired AI</span><time datetime="2026-09-04">2026-09-04</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/63d56961b22b.jpg" alt="配图"></p><p>据 WIRED 获悉，OpenAI 内部曾预计与 AI 编程工具 Cursor 的合作每年可带来超 10 亿美元收入，但在 Elon Musk 旗下 SpaceX 收购 Cursor 后，OpenAI 仍选择终止合作。此举凸显地缘政治与创始人个人关系对商业决策的深刻影响。对读者：评估 AI 生态合作时需将企业间政治与所有权变动纳入风险考量。</p><p class="news-entry-source"><a href="https://www.wired.com/story/openai-elon-musk-cursor-billion-revenue/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="sam-altman-为-gpt-6-astra-混乱发布致歉-付费用户被锁在门外" tabindex="-1">Sam Altman 为 GPT-6 Astra 混乱发布致歉，付费用户被锁在门外 <a class="header-anchor" href="#sam-altman-为-gpt-6-astra-混乱发布致歉-付费用户被锁在门外" aria-label="Permalink to &quot;Sam Altman 为 GPT-6 Astra 混乱发布致歉，付费用户被锁在门外&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-09-04">2026-09-04</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/1c0c10b1c50b.jpg" alt="配图"></p><p>OpenAI 发布 GPT-6 Astra 后数小时，CEO Sam Altman 便为“混乱的发布”道歉。该模型被公司称为“AGI 时代”的开端，但首发仅向部分 Daybreak 企业客户开放，大量付费订阅用户未能如期访问，引发不满。对读者：关注新模型实际可用性与企业级安全能力，而非营销话术。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/990060/altman-apologizes-messy-astra-rollout" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="google-gemini-spark-现可管理你的-google-photos-图库" tabindex="-1">Google Gemini Spark 现可管理你的 Google Photos 图库 <a class="header-anchor" href="#google-gemini-spark-现可管理你的-google-photos-图库" aria-label="Permalink to &quot;Google Gemini Spark 现可管理你的 Google Photos 图库&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-09-04">2026-09-04</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/8fb9ae5a0e70.jpg" alt="配图"></p><p>Google 的 Gemini Spark 新增 Google Photos 管理能力，可编辑和策划相册、创建共享合集、将照片转为日历事件等。该功能面向 AI Pro 和 Ultra 订阅用户开放，进一步将 AI 助手嵌入日常数字生活。对读者：AI 助手正从对话走向主动代理，可关注其与个人数据服务的深度集成。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/09/04/googles-gemini-spark-can-now-manage-your-google-photos-library/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="微软推出-project-zenith-为开发者打造的-无干扰-windows-体验" tabindex="-1">微软推出 Project Zenith：为开发者打造的“无干扰 Windows 体验” <a class="header-anchor" href="#微软推出-project-zenith-为开发者打造的-无干扰-windows-体验" aria-label="Permalink to &quot;微软推出 Project Zenith：为开发者打造的“无干扰 Windows 体验”&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-09-04">2026-09-04</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/c88c3971adde.jpg" alt="配图"></p><p>微软正式命名其开发者优化版 Windows 为 Project Zenith，面向配备 64GB 以上统一内存的新款开发者设备。该版本提供预配置的开发环境与精选工具链，支持本地运行 30B+ 参数模型，旨在减少干扰、提升开发效率。对读者：本地大模型开发门槛进一步降低，可关注相关硬件与系统生态。</p><p class="news-entry-source"><a href="https://www.theverge.com/news/990051/microsoft-project-zenith-windows-developers" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="gpt-6-astra-正式登场-烧了-10-万块-gpu-多项跑分逼近满分" tabindex="-1">GPT-6 Astra 正式登场：烧了 10 万块 GPU，多项跑分逼近满分 <a class="header-anchor" href="#gpt-6-astra-正式登场-烧了-10-万块-gpu-多项跑分逼近满分" aria-label="Permalink to &quot;GPT-6 Astra 正式登场：烧了 10 万块 GPU，多项跑分逼近满分&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-09-04">2026-09-04</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/059f164429ad.jpg" alt="配图"></p><p>OpenAI 正式发布 GPT-6 Astra，据称训练使用了 10 万块 GPU。模型在计算机使用、软件工程、网络安全与科研等场景能力突出，FrontierMath Tier 4 达 98%、ARC-AGI 3 达 99.9%、ExploitBench 达 100%，首次达到公司内部“关键级”安全门槛。对读者：前沿模型能力与安全评级并进，企业采用时可参考其基准表现与安全认证。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/mKGb7ZiPRlAiFDZCWK0v?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="magnitudedev-magnitude-为你的硬件运行最佳本地模型的开源推理服务器" tabindex="-1">magnitudedev/magnitude：为你的硬件运行最佳本地模型的开源推理服务器 <a class="header-anchor" href="#magnitudedev-magnitude-为你的硬件运行最佳本地模型的开源推理服务器" aria-label="Permalink to &quot;magnitudedev/magnitude：为你的硬件运行最佳本地模型的开源推理服务器&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">magnitudedev/magnitude</span><time datetime="2026-09-04">2026-09-04</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/b391e5bae3e3.png" alt="配图"></p><p>Magnitude 是一个开源推理服务器，旨在根据用户硬件自动运行最适合的本地模型，并可直接接入 Pi、OpenCode、Hermes、OpenClaw、Codex、Claude Code、Cline 等主流 AI 代理工具。对读者：自托管本地模型与现有 Agent 工作流集成更简单，值得尝试。</p><p class="news-entry-source"><a href="https://github.com/magnitudedev/magnitude" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="radixark-miles-面向企业的-llm-vlm-后训练强化学习框架" tabindex="-1">radixark/miles：面向企业的 LLM/VLM 后训练强化学习框架 <a class="header-anchor" href="#radixark-miles-面向企业的-llm-vlm-后训练强化学习框架" aria-label="Permalink to &quot;radixark/miles：面向企业的 LLM/VLM 后训练强化学习框架&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">radixark/miles</span><time datetime="2026-09-04">2026-09-04</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/e533939c8db2.png" alt="配图"></p><p>Miles 是一个面向企业的强化学习框架，用于 LLM 和 VLM 的后训练，从 slime 项目 fork 而来并与之共同演进。它旨在为企业提供更可控、可扩展的模型后训练能力。对读者：企业若需定制模型行为，可关注该框架与 slime 的生态协同。</p><p class="news-entry-source"><a href="https://github.com/radixark/miles" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="github-copilot-应用初学者指南-同时运行多个-agent" tabindex="-1">GitHub Copilot 应用初学者指南：同时运行多个 Agent <a class="header-anchor" href="#github-copilot-应用初学者指南-同时运行多个-agent" aria-label="Permalink to &quot;GitHub Copilot 应用初学者指南：同时运行多个 Agent&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">GitHub Blog</span><time datetime="2026-09-04">2026-09-04</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/be8831136553.png" alt="配图"></p><p>GitHub 官方博客发布教程，指导用户如何在 GitHub Copilot 应用中同时运行多个并行 Agent，并分享从“感到害怕”到“觉得强大”的体验转变。这标志着 AI 编程助手正从单线程辅助走向多智能体协作。对读者：掌握并行 Agent 工作流可显著提升复杂任务的开发效率。</p><p class="news-entry-source"><a href="https://github.blog/ai-and-ml/github-copilot/github-copilot-app-for-beginners-run-several-agents-at-once/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="人人都能搭-自己的-deepseek-harness-为何还在为-claude-code-们付费" tabindex="-1">人人都能搭“自己的 DeepSeek Harness”，为何还在为 Claude Code 们付费？ <a class="header-anchor" href="#人人都能搭-自己的-deepseek-harness-为何还在为-claude-code-们付费" aria-label="Permalink to &quot;人人都能搭“自己的 DeepSeek Harness”，为何还在为 Claude Code 们付费？&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-09-04">2026-09-04</time></p><p>文章探讨了 Coding Agent 领域的现状：Claude Code、Codex 等产品底层路径趋同，个人 Harness 项目大量涌现，甚至有人宣称“几百行代码就能重建 Cursor”。讨论聚焦于在模型与 Harness 都“卷不动”后，Coding Agent 还能卷什么。对读者：评估自建 Agent 工具链与商业产品的成本与收益，关注差异化价值。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/6Jc130IN2OaXqsPDIzmJ?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="astro-推出-satteri-rust-驱动的-markdown-mdx-处理器-构建速度最高提升-60" tabindex="-1">Astro 推出 Sätteri：Rust 驱动的 Markdown/MDX 处理器，构建速度最高提升 60% <a class="header-anchor" href="#astro-推出-satteri-rust-驱动的-markdown-mdx-处理器-构建速度最高提升-60" aria-label="Permalink to &quot;Astro 推出 Sätteri：Rust 驱动的 Markdown/MDX 处理器，构建速度最高提升 60%&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-09-04">2026-09-04</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/1d79fb17bbdc.jpg" alt="配图"></p><p>Astro 团队发布基于 Rust 的高性能 Markdown/MDX 处理器 Sätteri，并已作为 Astro 7.0 的默认核心组件。它采用 pulldown-cmark 与 Oxc 解析引擎，取代 unified 生态的 remark/rehype 管道，构建速度提升 15%–61%，已在 Astro 与 Cloudflare 文档站点落地。对读者：内容型站点构建性能优化有了新选择，可评估迁移收益。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/s1MDWGIV7yoxkCXmWJx8?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="科技爱好者周刊-第-411-期-openclaw-2-0-是一个缩影" tabindex="-1">科技爱好者周刊（第 411 期）：OpenClaw 2.0 是一个缩影 <a class="header-anchor" href="#科技爱好者周刊-第-411-期-openclaw-2-0-是一个缩影" aria-label="Permalink to &quot;科技爱好者周刊（第 411 期）：OpenClaw 2.0 是一个缩影&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">阮一峰的网络日志</span><time datetime="2026-09-04">2026-09-04</time></p><p>阮一峰科技爱好者周刊第 411 期发布，本期以 OpenClaw 2.0 为引，探讨 AI 时代开源项目快速迭代与热度消退的现象。OpenClaw 2.0 由 933 位贡献者合并 16000 个 PR，发布节奏已从每日改为每月。对读者：AI 生成代码主导的项目演进速度惊人，但也需关注其长期维护与社区治理模式。</p><p class="news-entry-source"><a href="http://www.ruanyifeng.com/blog/2026/09/weekly-issue-411.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div>',8)])])}const u=a(r,[["render",o]]);export{m as __pageData,u as default};
